#include <stdio.h>
#include <math.h>

#define MAX_N 300

typedef struct {
    double x, y;
} Point;

double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx*dx + dy*dy);
}

int count_inside(Point center, Point pts[], int n) {
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        if (dist(center, pts[i]) <= 1.0 + 1e-9)
            cnt++;
    }
    return cnt;
}

int main() {
    int n;
    Point pts[MAX_N];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &pts[i].x, &pts[i].y);
    }

    if (n == 1) {
        printf("1\n");
        return 0;
    }

    int best = 1;
    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            double d = dist(pts[i], pts[j]);
            if (d > 2.0) continue; // too far apart
            double mid_x = (pts[i].x + pts[j].x) / 2.0;
            double mid_y = (pts[i].y + pts[j].y) / 2.0;
            double h = sqrt(1.0 - (d/2.0)*(d/2.0));
            double dx = pts[j].x - pts[i].x;
            double dy = pts[j].y - pts[i].y;
            double norm = sqrt(dx*dx + dy*dy);
            double ux = -dy / norm;
            double uy = dx / norm;

            Point c1 = {mid_x + ux * h, mid_y + uy * h};
            Point c2 = {mid_x - ux * h, mid_y - uy * h};

            int cnt1 = count_inside(c1, pts, n);
            int cnt2 = count_inside(c2, pts, n);
            if (cnt1 > best) best = cnt1;
            if (cnt2 > best) best = cnt2;
        }
    }

    printf("%d\n", best);
    return 0;
}

