static const double EPS = 1e-9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for (int i = 0; i < N; ++i) cin >> x[i] >> y[i];

    if (N == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int ans = 1;

    // Check circles centered at each point (useful for N=1 and also harmless)
    for (int i = 0; i < N; ++i) {
        int cnt = 0;
        for (int k = 0; k < N; ++k) {
            double dx = x[k] - x[i];
            double dy = y[k] - y[i];
            if (dx * dx + dy * dy <= 1.0 + EPS) cnt++;
        }
        ans = max(ans, cnt);
    }

    // For any optimal circle, we can move it until either:
    // - it has one point on boundary, or
    // - it has two points on boundary.
    // It is enough to test centers of unit circles passing through pairs of points.
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            double dx = x[j] - x[i];
            double dy = y[j] - y[i];
            double d2 = dx * dx + dy * dy;
            double d = sqrt(d2);

            if (d > 2.0 + EPS) continue; // no unit circle can pass through both

            double mx = (x[i] + x[j]) / 2.0;
            double my = (y[i] + y[j]) / 2.0;

            // distance from midpoint to each possible center
            double h2 = 1.0 - (d * d) / 4.0;
            if (h2 < 0 && h2 > -EPS) h2 = 0;
            if (h2 < 0) continue;
            double h = sqrt(h2);

            // unit perpendicular vector to segment ij
            double ux = -dy / d;
            double uy = dx / d;

            for (int sgn : {-1, 1}) {
                double cx = mx + sgn * h * ux;
                double cy = my + sgn * h * uy;

                int cnt = 0;
                for (int k = 0; k < N; ++k) {
                    double ddx = x[k] - cx;
                    double ddy = y[k] - cy;
                    if (ddx * ddx + ddy * ddy <= 1.0 + EPS) cnt++;
                }
                ans = max(ans, cnt);
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class MaxPointsInUnitCircle {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        double[] x = new double[N];
        double[] y = new double[N];
        for (int i = 0; i < N; i++) {
            x[i] = sc.nextDouble();
            y[i] = sc.nextDouble();
        }

        if (N == 1) {
            System.out.println(1);
            return;
        }

        int maxCount = 1;
        double eps = 1e-9;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                double dx = x[j] - x[i];
                double dy = y[j] - y[i];
                double dist = Math.sqrt(dx * dx + dy * dy);
                if (dist > 2.0 + eps) continue; // too far apart

                double midX = (x[i] + x[j]) / 2.0;
                double midY = (y[i] + y[j]) / 2.0;
                double halfDist = dist / 2.0;
                double h = Math.sqrt(1.0 - halfDist * halfDist);
                // perpendicular direction
                double px = -dy / dist;
                double py = dx / dist;

                // two possible centers
                double cx1 = midX + h * px;
                double cy1 = midY + h * py;
                double cx2 = midX - h * px;
                double cy2 = midY - h * py;

                int count1 = 0, count2 = 0;
                for (int k = 0; k < N; k++) {
                    double d1 = Math.sqrt((x[k] - cx1) * (x[k] - cx1) + (y[k] - cy1) * (y[k] - cy1));
                    double d2 = Math.sqrt((x[k] - cx2) * (x[k] - cx2) + (y[k] - cy2) * (y[k] - cy2));
                    if (d1 <= 1.0 + eps) count1++;
                    if (d2 <= 1.0 + eps) count2++;
                }
                maxCount = Math.max(maxCount, Math.max(count1, count2));
            }
        }

        System.out.println(maxCount);
    }
}

