import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextDouble();
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double R = 1.0;
    static final double EPS = 1e-9;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Point[] p = new Point[N];
        for (int i = 0; i < N; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            p[i] = new Point(x, y);
        }

        if (N == 0) {
            System.out.println(0);
            return;
        }
        if (N == 1) {
            System.out.println(1);
            return;
        }

        int ans = 1;

        // Any optimal unit circle can be shifted until either:
        // - it has one point as center candidate neighborhood, or
        // - at least two points lie on its boundary.
        // So it is enough to test circles determined by every pair of points
        // whose distance is <= 2.
        for (int i = 0; i < N; i++) {
            // Circle centered at the point itself
            ans = Math.max(ans, countInside(p, p[i].x, p[i].y));

            for (int j = i + 1; j < N; j++) {
                double dx = p[j].x - p[i].x;
                double dy = p[j].y - p[i].y;
                double d2 = dx * dx + dy * dy;
                double d = Math.sqrt(d2);

                if (d > 2.0 + EPS) continue;
                if (d < EPS) continue; // same point; pair does not define unique circle

                double mx = (p[i].x + p[j].x) / 2.0;
                double my = (p[i].y + p[j].y) / 2.0;

                double h = Math.sqrt(Math.max(0.0, R * R - (d / 2.0) * (d / 2.0)));

                // Unit perpendicular vector
                double ux = -dy / d;
                double uy = dx / d;

                // Two possible centers
                double cx1 = mx + ux * h;
                double cy1 = my + uy * h;
                double cx2 = mx - ux * h;
                double cy2 = my - uy * h;

                ans = Math.max(ans, countInside(p, cx1, cy1));
                ans = Math.max(ans, countInside(p, cx2, cy2));
            }
        }

        System.out.println(ans);
    }

    static int countInside(Point[] p, double cx, double cy) {
        int cnt = 0;
        double limit = R * R + EPS;
        for (Point pt : p) {
            double dx = pt.x - cx;
            double dy = pt.y - cy;
            if (dx * dx + dy * dy <= limit) cnt++;
        }
        return cnt;
    }
}
